//! Galileo E1B primary codes (memory codes) and E1 acquisition.
//!
//! The E1B primary codes are 4092-chip *memory codes*: they are published as hex
//! tables in the Galileo Open Service SIS ICD and CANNOT be generated by an LFSR
//! (this is why `dsp_calib.rs` leaves Galileo out — an earlier version invented
//! a sequence, which made every Galileo result meaningless). The table below is
//! transcribed from two independent mirrors of the ICD code tables and
//! cross-checked digit-for-digit on 2026-08-23 (all 50 PRNs identical):
//!   - GNSS-SDR `src/core/system_parameters/Galileo_E1.h` (`GALILEO_E1_B_PRIMARY_CODE`)
//!     https://raw.githubusercontent.com/gnss-sdr/gnss-sdr/master/src/core/system_parameters/Galileo_E1.h
//!   - PocketSDR (T. Takasu) `python/sdr_code_gal.py` (`E1B`)
//!     https://raw.githubusercontent.com/tomojitakasu/PocketSDR/master/python/sdr_code_gal.py
//!
//! Acquisition mirrors the FFT circular-correlation structure of `gps::acquire`
//! with two E1-specific changes: the coherent block spans the full 4 ms code
//! period (4092 chips at 1.023 Mcps), and the local replica is BOC(1,1)-shaped.
//! E1B is CBOC(6,1,1/11); a plain-BPSK replica throws away correlation gain,
//! while a BOC(1,1) replica captures most of the CBOC energy. 4 ms coherent
//! blocks plus non-coherent sums absorb the 250 bps I/NAV data sign flips,
//! exactly as the 1 ms blocks absorb GPS data bits.

use num_complex::Complex;
use rustfft::{Fft, FftPlanner};
use std::f64::consts::PI;
use std::sync::Arc;

use crate::gps::{AcqResult, F_L1};

/// E1B primary code length in chips (4 ms period at 1.023 Mcps).
pub const CODE_LEN: usize = 4092;
/// E1B chip rate, same as GPS L1 C/A.
pub const CHIP_RATE: f64 = 1.023e6;
/// Number of E1B codes listed in the ICD table.
pub const N_PRNS: usize = 50;
const HEX_PER_CODE: usize = CODE_LEN / 4; // 1023 hex digits per code

